/// <summary>
/// PricingAttribute of table <c>SalesLine</c> field ReceiptDateConfirmed.
/// </summary>
[UPSPricingMetadataDiscovery][UPSPricingAttributeSourceDiscovery(UPSPricingAttributeSource::SalesLine, UPSPricingAttributeSourceLevel::Line)]
internal class UPSPricingAttributeSalesLineReceiptDateConfirmed extends UPSPricingAttributeSalesLine implements UPSIPricingAttribute
{
}

Method.Source:
public str getName()
{
    return fieldPName(SalesLine, ReceiptDateConfirmed);
}

public Set getAllowedValues()
{
    var         ret = new Set(Types::Date);
    SalesLine   salesLine;

    while select salesLine
        group by ReceiptDateConfirmed
    {
        if (! ret.in(salesLine.ReceiptDateConfirmed))
        {
            ret.add(salesLine.ReceiptDateConfirmed);
        }
    }
    return ret;
}

protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
{
    QueryBuildRange qbr;

    qbr = _qbds.addRange(fieldNum(SalesLine, ReceiptDateConfirmed));
    qbr.value(queryValue(_value));
}
